  "taxGuide.spain.step.inStore.identity": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Show passport and any residence evidence requested by the retailer. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.inStore.der": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Ask the Spanish store for the DER electronic refund document used by DIVA. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.inStore.check": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Check name, passport, residence, purchase, invoice and refund details before leaving the store. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.inStore.keep": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Keep the Tax Free document, receipts, travel proof and goods together. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.beforeDeparture.finalExit": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Validate at the final EU exit point, including when connecting through another EU member state. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.beforeDeparture.checkedBags": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — For checked baggage, complete customs validation before bag drop because goods must be presentable. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.beforeDeparture.deadlines": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Export within three months and return customs-confirmed Italian documentation to the seller within four months. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.beforeDeparture.deadline": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Export the goods within the official three-month deadline. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.customs.fallback": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — If electronic validation cannot be completed, follow the customs desk fallback and keep confirmation proof. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.customs.present": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Be ready to present goods, passport, documents, receipts and travel evidence. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.customs.otherEuExit": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — If the final EU exit is another member state, use that customs process with the documents. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.customs.diva": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Validate Spanish DER documents at DIVA terminals when Spain is the final EU exit. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.customs.intervention": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Go to customs if DIVA requires intervention or inspection. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.refund.afterValidation": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Refund processing starts only after customs confirms export. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.refund.methods": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Card, cash or transfer availability depends on the retailer or refund operator. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.step.refund.fees": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Operator fees, payment costs and exchange rates can reduce the final received amount. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.refund.method.card": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Card refund where selected and supported after validation. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.refund.method.cash": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Cash refund only at available authorised counters after validation. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.refund.method.transfer": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Bank transfer where selected and supported by the retailer or operator. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.deadline": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Goods must leave the EU within three months and the DER/DIVA document must be validated before refund processing. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.minimumExplanation": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Spain resolves as no statutory minimum, with no fake zero or positive threshold; DER issuance remains retailer/document based. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.vatExplanation": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — The statutory VAT rate remains official source data for calculation, not the traveller refund promise. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.estimatedRefundExplanation": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — The visible refund is an estimate before deductions and is separate from the statutory VAT rate. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.operatorFeeExplanation": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Retailer and refund-operator procedures, fees and payment routes determine the net refund. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.warning.validationRequired": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Without customs validation, the refund can be refused. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.warning.checkedBaggage": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Do not check goods before customs can inspect them. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.warning.finalEuExit": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Use the final EU exit point; do not validate only because the purchase country is earlier in the trip. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.warning.derPaper": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Spain DER/DIVA documents may need customs assistance or paper evidence when leaving via another EU state. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.warning.customsNotPayment": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — Customs certification confirms export but does not itself pay the refund. Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.source.schemeMinimum": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — official eligibility, minimum, retailer document and deadline evidence Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.source.customsDiva": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — DIVA validation, customs intervention and final-exit evidence Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.source.goodsConditions": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — official personal goods, baggage, exclusions and inspection evidence Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.source.refundProcess": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — AEAT refund operator, payment route and fee evidence Belgeleri gümrük için hazır tutun.",
  "taxGuide.spain.source.vatRate": "İspanya: mutat ikamet, belge, gümrük, iade, alışveriş — official standard VAT rate evidence Belgeleri gümrük için hazır tutun.",
  "taxFreeSource.germanCustomsZoll": "Alman Gümrüğü / Zoll",
  "taxFreeSource.agenciaTributariaAeat": "İspanya Vergi İdaresi / AEAT",
