  "taxGuide.denmark.minimumExplanation": "Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Olağan yol AB dışında ikamet eden tatil yolcuları içindir; Danimarka veya başka bir AB ülkesinde okuyan, çalışan ya da görevlendirilen kişiler uygun olmayabilir. Satıcı gönüllü katılır, uygun fatura verir ve gümrükçe doğrulanmış kanıtı aldıktan sonra iade yapar. Mallar yolcuyla çıkar, resmi üçüncü ay süresinde AB dışına gider; doğrudan AB dışına giden kayıtlı bagaj için bagaj tesliminden önce resmi dört saatlik pencerede Danimarka doğrulaması gerekebilir. Son AB çıkışı başka üye devletteyse doğrulama o gümrüğe aittir. Norveç ve Åland sakinleri olağan Danimarka eşiği yerine ithalat KDV kanıtı ve daha yüksek eşikli ayrı yolu izler. Ayrı madde 14.",
