  "taxGuide.finland.step.beforeShopping.goods": "Mal kontrolü. Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Olağan yolcu satışı AB’de veya Norveç’te yerleşik olmayan alıcılar içindir ve mutat ikamet ile kalıcı adres kanıtına dayanır. Satıcı veya yetkili iade işletmesi pasaport, ikamet, ayrıntılı makbuz, mallar, fiyat ve iade bilgilerini kaydeder, paketi mühürler; kullanılmamış mallar ve sağlam mühür Gümrük veya yetkili masa tarafından incelenir. İhracat resmi üç aylık sürede kişisel bagajla yapılır; son AB çıkışı Finlandiya veya başka üye devlet olabilir, yetkili masa yoksa Gümrük yedeği kullanılır. Norveç’te kalıcı ikamet edenler hemen taşıma ve Norveç ithalat KDV kanıtı yolunu izler. Ayrı madde 26.",
