  "taxGuide.norway.refund.method.card": "Kart iadesi. İade yöntemi. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 16.",
  "taxGuide.norway.refund.method.cash": "Nakit iade. İade yöntemi. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 17.",
  "taxGuide.norway.refund.method.transfer": "Banka transferi. İade yöntemi. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 18.",
