  "taxGuide.norway.vatExplanation": "Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 39.",
  "taxGuide.norway.estimatedRefundExplanation": "Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 9.",
  "taxGuide.norway.operatorFeeExplanation": "Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 15.",
  "taxGuide.norway.warning.validationRequired": "Uyarı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Norveç bir AB prosedürü değildir. Yolcu yurt dışında ikamet etmeli ve iadeye uygunluğu satıcıyla kararlaştırmalıdır; Norveç Gümrüğü iade ödemez. Resmi eşikler ve kanıt yolları ikamete bağlıdır: İsveç, Danimarka ve Finlandiya sakinleri ithalat KDV kanıtı yolunu, diğerleri faturaya dayalı yolu kullanır; Svalbard ve Jan Mayen ayrıdır. Birinci yol RD-0032 E formu, teslimden sonraki bir ay içinde personelli gümrükte form ve malların bizzat sunulması, ayrılıştan sonra geriye dönük tasdik olmaması ve tasdikli form dönünce satıcı ödemesidir. İkinci yol Norveç Gümrüğü tarafından damgalanmaması gereken özel Tax-Free Shopping belgesidir; ücretler uygulanabilir. Ayrı madde 44.",
