  "taxGuide.ireland.step.refund.afterValidation": "Rehber ayrıntısı. Bu anahtar kendi belge ve işlem konusunu ayrıca belirtir. Retail Export Scheme AB dışında ikamet eden turistler veya yolcular içindir; Kuzey İrlanda sakinleri hariçtir ve Büyük Britanya sakinleri güncel kanıtla uygun olabilir. Satıcı vergiyi tahsil eder, ihracat kuponu düzenler, ikamet kanıtı, giriş ve çıkış tarihleri ile imzalı beyan alır; ihracat kanıtından sonra doğrudan veya iade aracısıyla ödeme yapar. Mallar özel kullanım içindir, tedarikten sonraki üçüncü ayın son gününe kadar kişisel bagajda ihraç edilir, Gümrük incelemesine hazır tutulur ve hizmetler kapsam dışıdır. Yüksek değerli olmayan mallar, bilet ve süre koşulları sağlanırsa İrlanda son AB çıkışı olmasa da İrlanda tasdiki alabilir. Yüksek değerli mallar doğrudan Gümrük Memuruna sunulur; kutu veya aracı teslimi yeterli değildir. Ayrı madde 37.",
